<script>
window.certloomDesignRules={ajaxUrl:'/ajax',nonce:'fixture',previewUnavailable:'Preview unavailable',varies:'Inherited results vary across this selection.',emailDesigns:[{id:'email-issued',name:'Professional issued',purpose:'credential_issued'},{id:'email-issued-modern',name:'Modern issued',purpose:'credential_issued'},{id:'email-revoked',name:'Compliance revoked',purpose:'credential_revoked'}],globalEmailRules:{credential_issued:'email-issued'},noChange:'No change',inherit:'Inherit from parent',noGlobal:'No explicit global design',loadingTargets:'Loading…',targetsUnavailable:'Targets unavailable',loadMore:'Load more',noTargets:'No matching records.'};
window.__requests=[];
window.fetch=function(url,options){var params=new URLSearchParams(options.body||'');var data=Object.fromEntries(params.entries());window.__requests.push(data);if(data.action==='certloom_design_rules_preview'){var targets=JSON.parse(data.targets_json||'[]');var global=targets.length===1&&targets[0].scope_type==='global'&&targets[0].scope_id===0;var label=data.choice==='inherit'?(global?'No explicit global design':'Inherited result'):(data.choice==='no_change'?'Current effective design':data.choice.replace('design:','')==='11'?'Executive':data.choice.replace('design:','')==='12'?'Heritage':data.choice.indexOf('email')>=0?(data.choice.indexOf('revoked')>=0?'Compliance revoked':'Professional issued'):'Selected design');var kind=data.kind;return Promise.resolve({json:function(){return Promise.resolve({success:true,data:{html:'<div class="fixture-'+(kind==='certificate'?'cert':'email')+'">'+label+' preview</div>',label:label,source:global?'Global default':(targets.length>1?'Multiple scopes':'Inherited from parent'),varies:targets.length>1}});}});}
if(data.action==='certloom_design_rules_targets'){var scope=data.scope,page=parseInt(data.target_page||'1',10),search=(data.search||'').toLowerCase();var sets={issuer:[{key:'issuer:1',name:'Ecapla Institute',meta:'2 Programs',certificate:'Executive',email:'Professional issued'},{key:'issuer:2',name:'Northstar University',meta:'1 Program',certificate:'Inherited',email:'Inherited'},{key:'issuer:3',name:'Alpha Academy',meta:'4 Programs',certificate:'Heritage',email:'Inherited'}],program:[{key:'program:10',name:'Leadership Certification',meta:'Ecapla Institute',certificate:'Inherited',email:'Inherited'},{key:'program:11',name:'Safety Certification',meta:'Northstar University',certificate:'Heritage',email:'Inherited'},{key:'program:12',name:'Alpha Leadership',meta:'Alpha Academy',certificate:'Inherited',email:'Professional issued'}],batch:[{key:'batch:20',name:'September 2026',meta:'Leadership Certification',certificate:'Inherited',email:'Inherited'},{key:'batch:21',name:'Alpha Cohort',meta:'Alpha Leadership',certificate:'Inherited',email:'Inherited'}]};var all=sets[scope]||[];if(search){all=all.filter(function(x){return (x.name+' '+x.meta).toLowerCase().indexOf(search)>=0;});}var per=2,start=(page-1)*per,items=all.slice(start,start+per);return Promise.resolve({json:function(){return Promise.resolve({success:true,data:{items:items,total:all.length,page:page,hasMore:start+per<all.length}});}});}
return Promise.resolve({json:function(){return Promise.resolve({success:false,data:{message:'Unknown fixture action'}});}});};
